<style>
    .gs-public,.gs-public *{box-sizing:border-box}.gs-public{width:100%;min-height:100vh;min-height:100dvh;padding:32px 20px;background:linear-gradient(135deg,#061a31ad,#020c1c99),url('{{ asset('images/ccnhs-gate.webp') }}') center/cover no-repeat fixed;color:#0f172a;font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;font-size:14px;line-height:1.55}.gs-public a{color:#1d4ed8}.gs-public-shell{width:min(1040px,100%);margin:auto;border:1px solid #ffffff66;border-radius:24px;background:#f8fafc;box-shadow:0 24px 64px #02061750;overflow:hidden}.gs-public-head{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px 32px;background:linear-gradient(145deg,#304a5ef7,#2a374af7);color:#fff}.gs-public-head a{color:#dbeafe;font-weight:700}.gs-public-head p{color:#cbd5e1;font-size:12px;letter-spacing:1.6px;text-transform:uppercase}.gs-public-head h1{margin:3px 0 0;font-size:26px;font-weight:800}.gs-public-body{padding:32px}.gs-stepper{display:grid;grid-template-columns:repeat(var(--steps),1fr);gap:8px;margin-bottom:28px}.gs-step{padding:10px;border-bottom:3px solid #cbd5e1;color:#64748b;font-size:12px;font-weight:700}.gs-step[aria-current=step]{border-color:#1d4ed8;color:#1d4ed8}.gs-panel[hidden],.gs-public [hidden]{display:none!important}.gs-panel h2{margin:0 0 6px;font-size:24px;font-weight:800}.gs-panel h3{margin:24px 0 8px;font-size:16px;font-weight:800}.gs-muted{color:#64748b}.gs-notice{margin:18px 0;padding:14px 16px;border:1px solid #bfdbfe;border-radius:12px;background:#eff6ff;color:#1e3a8a}.gs-warning{border-color:#fde68a;background:#fffbeb;color:#92400e}.gs-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:22px}.gs-field{display:flex;flex-direction:column;gap:7px;color:#334155;font-size:13px;font-weight:700}.gs-field-wide{grid-column:1/-1}.gs-field input,.gs-field select,.gs-field textarea{width:100%;min-height:46px;padding:10px 14px;border:1px solid #94a3b8;border-radius:12px;background:#fff;color:#0f172a;font:inherit;font-size:16px}.gs-field textarea{resize:vertical}.gs-field input:focus,.gs-field select:focus,.gs-field textarea:focus{border-color:#1d4ed8;outline:3px solid #dbeafe;outline-offset:1px}.gs-field small{color:#64748b;font-weight:400}.gs-check{display:flex;align-items:flex-start;gap:10px;margin:14px 0;color:#334155}.gs-check input{width:18px;height:18px;margin-top:2px;accent-color:#1d4ed8;flex:none}.gs-actions{display:flex;justify-content:space-between;gap:12px;margin-top:28px}.gs-btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:10px 20px;border:1px solid #cbd5e1;border-radius:999px;background:#fff;color:#334155!important;font-weight:750;text-decoration:none;cursor:pointer}.gs-btn:disabled{opacity:.55;cursor:not-allowed}.gs-btn-primary{border-color:#1d4ed8;background:#1d4ed8;color:#fff!important}.gs-btn:hover:not(:disabled){background:#eff6ff}.gs-btn-primary:hover:not(:disabled){background:#1e40af}.gs-btn:focus-visible,.gs-public a:focus-visible,.gs-public input:focus-visible,.gs-public select:focus-visible{outline:3px solid #60a5fa;outline-offset:3px}.gs-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.gs-summary div{padding:14px;border:1px solid #e2e8f0;border-radius:12px;background:#fff}.gs-summary dt{color:#64748b;font-size:11px;text-transform:uppercase}.gs-summary dd{margin:5px 0 0;font-weight:750;overflow-wrap:anywhere}.gs-doc-links{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0}.gs-doc-links a{padding:16px;border:1px solid #bfdbfe;border-radius:12px;background:#eff6ff;font-weight:750}.gs-success{text-align:center;padding:40px 10px}.gs-success-mark{display:inline-flex;width:56px;height:56px;align-items:center;justify-content:center;border-radius:50%;background:#dcfce7;color:#166534;font-size:26px;font-weight:800}.gs-student-number{width:min(480px,100%);margin:24px auto;padding:20px;border:2px solid #bfdbfe;border-radius:16px;background:#eff6ff}.gs-student-number span,.gs-student-number small{display:block;color:#475569}.gs-student-number strong{display:block;margin:8px 0;color:#1e3a8a;font-size:20px;overflow-wrap:anywhere}.gs-status-preview{margin-top:24px;padding-top:20px;border-top:1px solid #e2e8f0}.gs-status-preview summary{color:#1d4ed8;font-weight:700;cursor:pointer}.gs-status-grid{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.gs-status-grid span{padding:7px 10px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:11px;font-weight:700}.gs-document{max-width:880px}.gs-document section{padding:20px 0;border-bottom:1px solid #e2e8f0}.gs-document h2{font-size:18px;margin:0 0 8px}.gs-document p,.gs-document li{color:#475569}.gs-document ul{padding-left:20px}.gs-version{padding:14px;border-radius:12px;background:#fffbeb;color:#92400e}.gs-required{color:#b91c1c}.gs-error{color:#b91c1c;font-size:12px;margin-top:5px}.gs-password-wrap{position:relative}.gs-password-wrap input{padding-right:50px}.gs-password-toggle{position:absolute;right:5px;top:3px;width:40px;height:40px;border:0;border-radius:50%;background:transparent;color:#475569;cursor:pointer}.gs-password-toggle:hover{background:#eff6ff}.gs-existing{text-align:center;margin-top:24px;color:#64748b}.gs-existing a{font-weight:700}.gs-link-child{margin-top:16px;padding:16px;border:1px dashed #94a3b8;border-radius:12px;background:#f8fafc}
    .gs-pending-badge{display:inline-flex;margin:14px 0;padding:7px 12px;border-radius:999px;background:#dbeafe;color:#1e40af;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.6px}
    @media(max-width:700px){.gs-public{padding:18px 12px;background-attachment:scroll}.gs-public-head{align-items:flex-start;padding:22px;flex-direction:column}.gs-public-body{padding:24px 20px}.gs-stepper{overflow-x:auto}.gs-step{min-width:110px}.gs-grid,.gs-doc-links,.gs-summary{grid-template-columns:1fr}.gs-field-wide{grid-column:auto}.gs-actions{flex-wrap:wrap}.gs-actions .gs-btn{flex:1}.gs-public-head h1{font-size:23px}}
</style>
